"use strict";

/**
 * Pay slips are filled automatically every quincena and can be edited by hand.
 *
 * - hoursWorked / overtimeHours / hourlyRate: snapshot of the data the amounts
 *   were computed from (shown on the slip editor, audit trail).
 * - manualFields: amount columns edited by hand. Automatic refreshes only
 *   recompute the fields NOT listed here, so manual edits always stick.
 * - autoGenerated: created by the biweekly job (vs. by a user).
 *
 * Existing rows flagged isManual keep every amount as manual so nothing that
 * was typed by hand is ever overwritten by the new automatic refresh.
 *
 * @type {import('sequelize-cli').Migration}
 */

const AMOUNT_FIELDS = [
  "regularSalary",
  "overtimePay",
  "mileage",
  "others",
  "socialCharges",
  "deductions",
];

module.exports = {
  up: async (queryInterface, Sequelize) => {
    await queryInterface.sequelize.transaction(async (transaction) => {
      await queryInterface.addColumn(
        "payments",
        "hoursWorked",
        { type: Sequelize.DECIMAL(8, 2), allowNull: true },
        { transaction },
      );
      await queryInterface.addColumn(
        "payments",
        "overtimeHours",
        { type: Sequelize.DECIMAL(8, 2), allowNull: true },
        { transaction },
      );
      await queryInterface.addColumn(
        "payments",
        "hourlyRate",
        { type: Sequelize.DECIMAL(12, 2), allowNull: true },
        { transaction },
      );
      await queryInterface.addColumn(
        "payments",
        "manualFields",
        { type: Sequelize.JSONB, allowNull: false, defaultValue: [] },
        { transaction },
      );
      await queryInterface.addColumn(
        "payments",
        "autoGenerated",
        { type: Sequelize.BOOLEAN, allowNull: false, defaultValue: false },
        { transaction },
      );

      await queryInterface.sequelize.query(
        `UPDATE payments SET "manualFields" = :fields::jsonb WHERE "isManual" = true`,
        { replacements: { fields: JSON.stringify(AMOUNT_FIELDS) }, transaction },
      );
    });
  },

  down: async (queryInterface) => {
    await queryInterface.sequelize.transaction(async (transaction) => {
      for (const column of ["autoGenerated", "manualFields", "hourlyRate", "overtimeHours", "hoursWorked"]) {
        // eslint-disable-next-line no-await-in-loop
        await queryInterface.removeColumn("payments", column, { transaction });
      }
    });
  },
};
